// Vulnerable code snippet: Improper use of Java's java.io.File API without proper validation or sanitization
// This code allows arbitrary file access and could lead to path traversal attacks
import java.io.File;
import java.io.IOException;

public class VulnerableFileAccess {
    public void readUserFile(String userInput) {
        // vulnerable: directly using user input in file path without validation
        String filePath = "/home/user/" + userInput; // vulnerable: user input is concatenated directly

        File file = new File(filePath);

        try {
            if (file.exists()) {
                // This could lead to reading sensitive files or executing malicious commands
                System.out.println("File content: " + file.read());
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + e.getMessage());
        }
    }
}

// vulnerable: No input validation, no restriction on file paths, no checks for file existence or permissions
// This creates a risk of path traversal and unauthorized access to system files
// Example: userInput = "../etc/passwd" could lead to reading system passwords

