// Fixed code snippet: Proper input validation and secure file handling
// Uses safe path construction and avoids direct user input in file paths
import java.io.File;
import java.io.IOException;

public class SecureFileAccess {
    public void readUserFile(String userInput) {
        // Fixed: Validate input and sanitize path
        // Only allow safe, known paths (e.g., within a specific directory)
        if (userInput == null || userInput.trim().isEmpty()) {
            System.out.println("Input cannot be empty.");
            return;
        }

        // Sanitize input: only allow alphanumeric characters and common file separators
        String sanitizedInput = userInput.trim();
        // Restrict to only allowed characters (e.g., letters, numbers, dots, underscores)
        sanitizedInput = sanitizedInput.replaceAll("[^a-zA-Z0-9._]", "");

        // Define a safe base directory (e.g., within application's own folder)
        String safeBasePath = "/home/user/appdata/";
        String filePath = safeBasePath + sanitizedInput;

        File file = new File(filePath);

        // Validate file exists and is within the safe directory
        if (file.exists() && file.isFile() && isWithinSafeDirectory(file)) {
            try {
                // Read file content safely
                java.nio.file.Files.readAllBytes(file.toPath());
                System.out.println("File content read successfully.");
            } catch (IOException e) {
                System.out.println("Error reading file: " + e.getMessage());
            }
        } else {
            System.out.println("File not found or access denied.");
        }
    }

    // Helper method to check if file is within the safe directory
    private boolean isWithinSafeDirectory(File file) {
        String basePath = "/home/user/appdata/";
        String fileAbsolutePath = file.getAbsolutePath();
        return fileAbsolutePath.startsWith(basePath);
    }
}

// Security improvements:
// - Input is validated and sanitized to prevent path traversal
// - File path is constructed using a known safe base directory
// - Access is restricted to only files within the safe directory
// - No direct user input is used in file paths
// This prevents vulnerabilities such as path traversal and unauthorized file access
